#include <bits/stdc++.h>
using namespace std;

constexpr long long BASE = 31;
constexpr array<long long, 2> MODULI{1000000007, 1000000009};
struct Fingerprint {
    int length;
    array<long long, 2> hash;
};

class StringHash {
    array<vector<long long>, 2> prefix, power;
public:
    explicit StringHash(const string& text) {
        int n = static_cast<int>(text.size());

    for (int part = 0; part < 2; ++part) {
        prefix[part].resize(n + 1);
        power[part].assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            int value = text[i] - 'a' + 1;
            prefix[part][i + 1] = (prefix[part][i] * BASE + value) % MODULI[part];
            power[part][i + 1] = power[part][i] * BASE % MODULI[part];
        }
    }
}

    Fingerprint substring(int l, int r) const {
        Fingerprint result{r - l, {0, 0}};
        for (int part = 0; part < 2; ++part) {
            long long removed = prefix[part][l] * power[part][r - l] % MODULI[part];
            result.hash[part] = (prefix[part][r] - removed + MODULI[part]) % MODULI[part];
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string text;
    int q;
    cin >> text >> q;
    StringHash hashes(text);
    for (int query = 0; query < q; ++query) {
        int l, r;
        cin >> l >> r;
        Fingerprint result = hashes.substring(l - 1, r);
        cout << result.length << ' ' << result.hash[0] << ' ' << result.hash[1] << '\n';
    }
}

